?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pelaporan | SICERDAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/../../layouts/sidebar.php';?><div class="main-wrapper"><?php include __DIR__.'/../../layouts/navbar.php';?><main class="content"><div class="page-heading"><div><p>Realisasi Kegiatan</p><h1>Laporan & Penilaian</h1></div></div><div class="row g-3"><div class="col-lg-4"><div class="panel p-3"><h2 class="fs-6">Tambah Laporan</h2><form method="post" class="vstack gap-2"><input class="form-control" name="nama_perusahaan" placeholder="Nama perusahaan" required><input class="form-control" name="jenis_kegiatan" placeholder="Jenis kegiatan" required><input type="date" class="form-control" name="tanggal_laporan" value="<?=date('Y-m-d')?>"><input type="number" step="0.01" class="form-control" name="luas_realisasi" placeholder="Luas realisasi"><input type="number" class="form-control" name="jumlah_tanaman" placeholder="Jumlah tanaman"><input class="form-control" name="jenis_tanaman" placeholder="Jenis tanaman"><input type="number" min="0" max="100" class="form-control" name="persentase" placeholder="Persentase keberhasilan"><textarea class="form-control" name="catatan_petugas" rows="2" placeholder="Catatan petugas"></textarea><button class="btn btn-orange">Simpan</button></form></div></div><div class="col-lg-8"><div class="panel table-panel"><div class="table-responsive"><table class="table sicerdas-table"><thead><tr><th>No. Laporan</th><th>Perusahaan</th><th>Kegiatan</th><th>Tanggal</th><th>Realisasi</th><th>Keberhasilan</th></tr></thead><tbody><?php $rows=$pdo->query('SELECT * FROM laporan ORDER BY created_at DESC')->fetchAll();foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nomor_laporan'])?></td><td><?=htmlspecialchars($r['nama_perusahaan'])?></td><td><?=htmlspecialchars($r['jenis_kegiatan'])?></td><td><?=date('d/m/Y',strtotime($r['tanggal_laporan']))?></td><td><?=number_format((float)$r['luas_realisasi'],2)?> Ha</td><td><?= (int)$r['persentase_keberhasilan']?>%</td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="text-center py-4">Belum ada laporan.</td></tr><?php endif?></tbody></table></div></div></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
